<template>
    <div ref="list" :class="cx('root')" :data-p="dataP" v-bind="ptmi('root')">
        <button
            v-if="showNavigators && isPrevButtonEnabled"
            ref="prevButton"
            v-ripple
            type="button"
            :class="cx('prevButton')"
            :aria-label="prevButtonAriaLabel"
            :tabindex="$pcTabs.tabindex"
            @click="onPrevButtonClick"
            v-bind="ptm('prevButton')"
            data-pc-group-section="navigator"
        >
            <component :is="templates.previcon || 'ChevronLeft'" aria-hidden="true" v-bind="ptm('prevIcon')" />
        </button>
        <div ref="content" :class="cx('content')" role="tablist" aria-orientation="horizontal" @scroll="onScroll" v-bind="ptm('content')">
            <slot></slot>
            <span ref="inkbar" :class="cx('activeBar')" role="presentation" aria-hidden="true" v-bind="ptm('activeBar')"></span>
        </div>
        <button
            v-if="showNavigators && isNextButtonEnabled"
            ref="nextButton"
            v-ripple
            type="button"
            :class="cx('nextButton')"
            :aria-label="nextButtonAriaLabel"
            :tabindex="$pcTabs.tabindex"
            @click="onNextButtonClick"
            v-bind="ptm('nextButton')"
            data-pc-group-section="navigator"
        >
            <component :is="templates.nexticon || 'ChevronRight'" aria-hidden="true" v-bind="ptm('nextIcon')" />
        </button>
    </div>
</template>

<script>
import ChevronLeft from '@primeicons/vue/chevron-left';
import ChevronRight from '@primeicons/vue/chevron-right';
import { cn } from '@primeuix/utils';
import { findSingle, getWidth, isRTL } from '@primeuix/utils/dom';
import Ripple from 'primevue/ripple';
import BaseTabList from './BaseTabList.vue';

export default {
    name: 'TabList',
    extends: BaseTabList,
    inheritAttrs: false,
    inject: ['$pcTabs'],
    data() {
        return {
            isPrevButtonEnabled: false,
            isNextButtonEnabled: true
        };
    },
    resizeObserver: undefined,
    inkBarObserver: undefined,
    mountTimer: null,
    watch: {
        showNavigators(newValue) {
            newValue ? this.bindResizeObserver() : this.unbindResizeObserver();
        },
        activeValue: {
            flush: 'post',
            handler() {
                this.updateInkBar();
                this.bindInkBarObserver();

                const { content } = this.$refs;
                const activeTab = content ? findSingle(content, '[data-pc-name="tab"][data-p-active="true"]') : null;

                if (content && activeTab) this.$pcTabs.scrollToActiveTab(content, activeTab);
            }
        }
    },
    mounted() {
        this.mountTimer = setTimeout(() => {
            this.mountTimer = null;
            this.updateInkBar();
            this.bindInkBarObserver();
        }, 150);

        if (this.showNavigators) {
            this.updateButtonState();
            this.bindResizeObserver();
        }
    },
    updated() {
        this.showNavigators && this.updateButtonState();
    },
    beforeUnmount() {
        if (this.mountTimer) {
            clearTimeout(this.mountTimer);
            this.mountTimer = null;
        }

        this.unbindResizeObserver();
        this.unbindInkBarObserver();
    },
    methods: {
        onScroll(event) {
            this.showNavigators && this.updateButtonState();

            event.preventDefault();
        },
        onPrevButtonClick() {
            const content = this.$refs.content;
            const buttonWidths = this.getVisibleButtonWidths();
            const width = getWidth(content) - buttonWidths;
            const currentScrollLeft = Math.abs(content.scrollLeft);
            const scrollStep = width * 0.8;
            const targetScrollLeft = currentScrollLeft - scrollStep;
            const scrollLeft = Math.max(targetScrollLeft, 0);

            content.scrollLeft = isRTL(content) ? -1 * scrollLeft : scrollLeft;
        },
        onNextButtonClick() {
            const content = this.$refs.content;
            const buttonWidths = this.getVisibleButtonWidths();
            const width = getWidth(content) - buttonWidths;
            const currentScrollLeft = Math.abs(content.scrollLeft);
            const scrollStep = width * 0.8;
            const targetScrollLeft = currentScrollLeft + scrollStep;
            const maxScrollLeft = content.scrollWidth - width;
            const scrollLeft = Math.min(targetScrollLeft, maxScrollLeft);

            content.scrollLeft = isRTL(content) ? -1 * scrollLeft : scrollLeft;
        },
        bindResizeObserver() {
            this.resizeObserver = new ResizeObserver(() => this.updateButtonState());
            this.resizeObserver.observe(this.$refs.list);
        },
        unbindResizeObserver() {
            this.resizeObserver?.unobserve(this.$refs.list);
            this.resizeObserver = undefined;
        },
        bindInkBarObserver() {
            this.unbindInkBarObserver();

            const { content } = this.$refs;
            const activeTab = findSingle(content, '[data-pc-name="tab"][data-p-active="true"]');

            if (activeTab) {
                this.inkBarObserver = new ResizeObserver(() => this.updateInkBar());
                this.inkBarObserver.observe(activeTab);
            }
        },
        unbindInkBarObserver() {
            this.inkBarObserver?.disconnect();
            this.inkBarObserver = undefined;
        },
        updateInkBar() {
            const { content, inkbar } = this.$refs;

            if (!inkbar) return;

            const activeTab = findSingle(content, '[data-pc-name="tab"][data-p-active="true"]');

            if (!activeTab) return;

            inkbar.style.setProperty('--px-active-bar-width', activeTab.offsetWidth + 'px');
            inkbar.style.setProperty('--px-active-bar-height', activeTab.offsetHeight + 'px');
            inkbar.style.setProperty('--px-active-bar-left', activeTab.offsetLeft + 'px');
            inkbar.style.setProperty('--px-active-bar-top', activeTab.offsetTop + 'px');
        },
        updateButtonState() {
            const { list, content } = this.$refs;
            const { scrollWidth, offsetWidth } = content;
            const scrollLeft = Math.abs(content.scrollLeft);
            const width = getWidth(content);

            this.isPrevButtonEnabled = scrollLeft !== 0;
            this.isNextButtonEnabled = list.offsetWidth >= offsetWidth && parseInt(scrollLeft) !== scrollWidth - width;
        },
        getVisibleButtonWidths() {
            const { prevButton, nextButton } = this.$refs;
            let width = 0;

            if (this.showNavigators) {
                width = (prevButton?.offsetWidth || 0) + (nextButton?.offsetWidth || 0);
            }

            return width;
        }
    },
    computed: {
        templates() {
            return this.$pcTabs.$slots;
        },
        activeValue() {
            return this.$pcTabs.d_value;
        },
        showNavigators() {
            return this.$pcTabs.showNavigators;
        },
        prevButtonAriaLabel() {
            return this.$primevue.config.locale.aria ? this.$primevue.config.locale.aria.previous : undefined;
        },
        nextButtonAriaLabel() {
            return this.$primevue.config.locale.aria ? this.$primevue.config.locale.aria.next : undefined;
        },
        dataP() {
            return cn({
                scrollable: this.$pcTabs.scrollable
            });
        }
    },
    components: {
        ChevronLeft,
        ChevronRight
    },
    directives: {
        ripple: Ripple
    }
};
</script>
